    : ['Aucune échéance à venir en TND : rien ne modifie le solde du dernier relevé.']),
  a_traiter: (l) => (l.length
    ? ['En attente de décision :', ...l.map((x) => `• ${x.nombre} ${LIBELLES_A_TRAITER[x.type] ?? x.type}`)]
    : ['Rien n\'attend de décision.']),
  etat_facture: (l, p, d) => {
