function delaiDemande(corps) {
  const details = corps?.error?.details ?? [];
  for (const d of details) {
    const m = /^(\d+(?:\.\d+)?)s$/.exec(String(d?.retryDelay ?? ''));
    if (m) return Math.ceil(Number(m[1]) * 1000);
