 * @returns {'quota_journalier_epuise'|'quota_minute'}
 */
function classerErreur429(corps) {
  const texte = JSON.stringify(corps ?? {});
  if (/quota_exceeded|PerDay|per[ _-]?day|daily/i.test(texte)) return 'quota_journalier_epuise';
