const DATE = /^(\d{4})-(\d{2})-(\d{2})$/;
const MOIS = /^(\d{4})-(\d{2})$/;
function dateValide(t) {
  const m = DATE.exec(t);
  if (!m) return false;
  const d = new Date(`${t}T00:00:00Z`);
  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === t;
}

/**
